class Component extends DCLogic {
  componentDidMount(){ const go=()=>window.SWD&&window.SW_GEO_SP?SWD.ready(()=>this.init()):setTimeout(go,30); go(); }
  init(){
    const D=SW_DEMO_DATA, CF=SW_DEMO, SUB=CF.sub.SP, $=id=>document.getElementById(id), MU=SWD.munis(), G=SW_GEO_SP;
    SWD.page({active:'geral',lv:'SUB',label:'Visão geral'});
    const M={
      pop:{n:'População',sm:'População',t:'População por município',s:'Pessoas contadas no Censo 2022.',v:D.pop,src:'pop',col:'Pessoas',fmt:v=>SWD.mi(v,true),cuts:[5e3,1e4,5e4,1e5,5e5],legend:['até 5 mil','5–10 mil','10–50 mil','50–100 mil','100–500 mil','500 mil ou mais'],big:v=>SWD.mi(v)},
      dens:{n:'Densidade',sm:'Densidade',t:'Densidade, pessoas por km²',s:'População do Censo 2022 dividida pela área do município.',v:D.dens,src:'dens',col:'hab/km²',fmt:v=>SWD.num(v,1),cuts:[10,25,50,100,500],legend:['até 10','10–25','25–50','50–100','100–500','500 ou mais'],big:v=>SWD.num(v,1)+'<small>hab/km²</small>'},
      cresc:{n:'Crescimento 2010–2022',sm:'Crescimento',t:'Crescimento entre os Censos 2010 e 2022',s:'Taxa média de crescimento ao ano.',v:D.tx,src:'pop',col:'% ao ano',fmt:v=>SWD.sgn(v,2,'%'),cuts:SWD.GROW.cuts,legend:SWD.GROW.legend,big:v=>SWD.sgn(v,2)+'<small>% ao ano</small>'},
      idmed:{n:'Idade mediana',sm:'Idade',t:'Idade mediana',s:'Metade das pessoas tem menos que esta idade.',v:D.idmed,src:'pyr',col:'Anos',fmt:v=>SWD.num(v,1),cuts:[33,36,38,40,42],legend:['até 33 anos','33–36','36–38','38–40','40–42','42 ou mais'],big:v=>SWD.num(v,1)+'<small>anos</small>'}
    };
    const st={m:SWD.q.get('m')||'pop',sel:SWD.q.get('mu')||'3550308',hov:null,q:'',r:''};
    $('rgl').textContent=SUB.regionLabel;
    $('reg').innerHTML=`<option value="">Todas</option>`+[...new Set(MU.map(m=>G.meta[m][1]))].sort().map(r=>`<option>${r}</option>`).join('');
    $('reg').onchange=e=>{st.r=e.target.value;filt()};
    SWD.searchBox($('search'),`Buscar entre ${MU.length} ${SUB.units}`,v=>{st.q=SWD.norm(v.trim());filt()});
    const keep=m=>(!st.r||G.meta[m][1]===st.r)&&(!st.q||SWD.norm(G.meta[m][0]).includes(st.q));
    const map=new SWD.MuniMap($('map'),{aria:`Mapa dos ${MU.length} ${SUB.units}`,onHover:m=>{st.hov=m;draw()},onClick:m=>{st.sel=m;draw()}});
    const rank=new SWD.LongRank($('rank'),{onHover:m=>{st.hov=m;draw()},onClick:m=>{st.sel=m;draw()}});
    SWD.seg($('meas'),Object.entries(M).map(([k,m])=>[k,m.n,m.sm]),st.m,k=>{st.m=k;paint();draw()},'Medida do mapa');
    const filt=()=>{ const vis=MU.filter(keep); if(st.q&&vis.length&&!vis.includes(st.sel)) st.sel=vis[0]; paint(); draw(); };
    const paint=()=>{ const m=M[st.m];
      $('vt').textContent=m.t; $('vs').textContent=m.s; $('vstamp').innerHTML=SWD.stamp(m.src);
      map.update(u=>{const x=m.v[u]; return x==null?{hatch:true}:{f:`var(--g${SWD.cls(x,m.cuts)})`}}, (st.q||st.r)?keep:null);
      $('legend').innerHTML=SWD.legend(m.legend,'g',MU.filter(u=>m.v[u]==null).length,SUB.units)+`<div class="lgx" style="margin-top:10px"><span><i style="background:var(--flag)"></i>Selecionado, no ${SUB.flag.name}</span></div>`;
      $('src').innerHTML=SWD.srcLine([m.src]); };
    const draw=()=>{ const m=M[st.m], u=st.hov||st.sel, x=m.v[u], vals=MU.filter(k=>m.v[k]!=null).sort((a,b)=>m.v[b]-m.v[a]), r=vals.indexOf(u)+1, e0=D.ts.e0.SP[2022];
      map.mark(st.sel,st.hov);
      const fact=(l,v)=>`<div class="fact"><span>${l}</span><b>${v}</b></div>`;
      $('card').innerHTML=`<div class="card" aria-live="polite">
        <div class="meta">${G.meta[u][1]} · ${r?`${r}º de ${MU.length} em ${m.n.toLowerCase()}`:'sem dado'}</div>
        <div class="row1"><div class="nm">${SWD.name(u)}</div>${x==null?SWD.nodata():`<div class="big">${m.big(x)}</div>`}</div>
        <div style="margin-top:2px">${SWD.stamp(m.src)}</div>
        <div class="facts">${fact('Censo 2022',SWD.int(D.pop[u])+' pessoas')}${fact(`Estimativa ${D.estYear} ${SWD.freq('est')}`,SWD.int(D.est[u]))}${fact('Crescimento 2010–2022',SWD.sgn(D.tx[u],2,'% ao ano'))}${fact('Idade mediana',SWD.num(D.idmed[u],1)+' anos')}${fact('Pessoas por domicílio',D.dom[u][1]==null?'sem dado':SWD.num(D.dom[u][1],2))}</div>
        <div style="margin-top:10px">${SWD.lvbox('estado',`Esperança de vida não sai por município. Em ${SUB.name}: ${SWD.num(e0,1)} anos (2022, projeção).`)}</div>
        <div class="line" style="font-size:15px"><a href="${SWD.href('SUB','ficha','m='+u)}">Abrir a ficha de ${SWD.name(u)} →</a></div></div>`;
      rank.render({rows:MU.map(k=>({id:k,v:m.v[k],txt:m.v[k]==null?'sem dado':m.fmt(m.v[k])})),sel:st.sel,hov:st.hov,col:m.col,head:SUB.Unit,filter:(st.q||st.r)?keep:null});
    };
    paint(); draw();
  }
  renderVals(){ return {}; }
}
